/* instance['name']: the reference to one export (KeyError if there is none) */
static PyObject *Instance_subscript(PyObject *self, PyObject *key) {
    const char *name = PyUnicode_Check(key) ? PyUnicode_AsUTF8AndSize(key, NULL) : NULL;
    if (name == NULL) {
        if (PyErr_Occurred() && !PyErr_ExceptionMatches(PyExc_TypeError)) return NULL;
        PyErr_Clear();
        PyErr_SetObject(PyExc_KeyError, key);
        return NULL;
    }
    for (int k = 0; export_table[k].name != NULL; k++) {
        if (strcmp(name, export_table[k].name) == 0) return export_ref(self, k);
    }
    PyErr_SetObject(PyExc_KeyError, key);
    return NULL;
}

/* instance.__exports__: {name: a reference to the export}, to be given as an import of another instance */
static PyObject *Instance_exports(PyObject *self, void *closure) {
    (void)closure;
    PyObject *result = PyDict_New();
    if (result == NULL) return NULL;
    for (int k = 0; export_table[k].name != NULL; k++) {
        PyObject *name = PyUnicode_FromString(export_table[k].name);
        PyObject *ref = name != NULL ? export_ref(self, k) : NULL;
        int bad = ref == NULL || PyDict_SetItem(result, name, ref) != 0;
        Py_XDECREF(name);
        Py_XDECREF(ref);
        if (bad) { Py_DECREF(result); return NULL; }
    }
    return result;
}

static PyMethodDef Instance_methods[] = {
    {"tick", (PyCFunction)(void (*)(void))Instance_f0, METH_FASTCALL, "tick() -> i32"},
    {"count", (PyCFunction)(void (*)(void))Instance_f1, METH_FASTCALL, "count() -> i32"},
    {"reset", (PyCFunction)(void (*)(void))Instance_f2, METH_FASTCALL, "reset() -> None"},
    {"peek", (PyCFunction)(void (*)(void))Instance_f3, METH_FASTCALL, "peek(i32) -> i32"},
    {"poke", (PyCFunction)(void (*)(void))Instance_f4, METH_FASTCALL, "poke(i32, i32) -> None"},
    {NULL, NULL, 0, NULL}
};

static PyGetSetDef Instance_getset[] = {
    {"__exports__", (getter)Instance_exports, NULL, "{name: a reference to the export}: what another instance can take as an import", NULL},
    {NULL, NULL, NULL, NULL, NULL}
};

static PyMemberDef Instance_members[] = {
    {"__weaklistoffset__", T_PYSSIZET, offsetof(InstanceObject, weakreflist), READONLY, NULL},
    {NULL, 0, 0, 0, NULL}
};

static PyType_Slot instance_slots[] = {
    {Py_tp_new, Instance_new},
    {Py_tp_dealloc, Instance_dealloc},
    {Py_tp_traverse, Instance_traverse},
    {Py_tp_clear, Instance_clear},
    {Py_tp_methods, Instance_methods},
    {Py_mp_subscript, Instance_subscript},
    {Py_tp_getset, Instance_getset},
    {Py_tp_members, Instance_members},
    {Py_tp_doc, (void *)"An instance of the WebAssembly module"},
    {0, NULL}
};
static PyType_Spec instance_spec = {"linkdemo._app.Instance", sizeof(InstanceObject), 0, Py_TPFLAGS_DEFAULT | Py_TPFLAGS_HAVE_GC | Py_TPFLAGS_BASETYPE, instance_slots};

static struct PyModuleDef module_def = {PyModuleDef_HEAD_INIT, "linkdemo._app", "A WebAssembly module as a native extension (wasmext, wasm2c)", -1, NULL};

PyMODINIT_FUNC PyInit__app(void) {
    PyObject *m;
    wasm_rt_init();
    m = PyModule_Create(&module_def);
    if (m == NULL) return NULL;
    TrapError = PyErr_NewExceptionWithDoc("linkdemo._app.Trap", "The WebAssembly code trapped", PyExc_RuntimeError, NULL);
    LinkError = PyErr_NewExceptionWithDoc("linkdemo._app.LinkError", "An import is missing", PyExc_Exception, NULL);
    InstanceType = (PyTypeObject *)PyType_FromSpec(&instance_spec);
    if (!TrapError || !LinkError || !InstanceType) goto fail;
    if (PyModule_AddObjectRef(m, "Trap", TrapError) < 0) goto fail;
    if (PyModule_AddObjectRef(m, "LinkError", LinkError) < 0) goto fail;
    if (PyModule_AddObjectRef(m, "Instance", (PyObject *)InstanceType) < 0) goto fail;
    return m;
fail:
    Py_DECREF(m);
    return NULL;
}
